//! Deterministic randomized round-trip test. A small LCG PRNG (no external
//! dependencies) generates a large sequence of opcodes across multiple frames,
//! written by a `Guest` and read back by a `Host`. It asserts exact integrity:
//! opcode count, field-for-field equality, and arena string contents. Fixed
//! conformance vectors can miss off-by-one / wraparound bugs; a long randomized
//! run makes the ring wrap many times.

use pathland_opcode::{
    component_type, init_memory, property_id, value_type, Guest, Host, MemoryLayout, Opcode,
    APPEND,
};

/// Simple deterministic LCG (Numerical Recipes). Returns a value in [0, 2^32).
struct Lcg(u64);

impl Lcg {
    fn next_u32(&mut self) -> u32 {
        self.0 = self.0.wrapping_mul(1664525).wrapping_add(1013904223);
        (self.0 >> 32) as u32
    }

    fn below(&mut self, n: u32) -> u32 {
        self.next_u32() % n
    }
}

#[test]
fn random_sequences_round_trip_exactly() {
    // Small ring so the write cursor wraps many times over the run.
    let layout = MemoryLayout {
        slot_count: 16,
        arena_bytes: 1 << 16,
    };
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    // The full opcode stream we expect to read back.
    let mut expected: Vec<Opcode> = Vec::new();
    let mut arena_strings: Vec<(u32, String)> = Vec::new();

    let mut rng = Lcg(0xC0FF_EE00);
    let frames = 200usize;
    let max_ops = 60usize;

    {
        let mut g = Guest::new(&mut mem, &layout);
        let mut node_counter = 0u32;
        for _ in 0..frames {
            g.begin_frame();
            let n = (rng.below(max_ops as u32) as usize) + 1;
            for _ in 0..n {
                // 0..5 select an opcode kind; create_node + set_property dominate.
                match rng.below(6) {
                    0 => {
                        node_counter += 1;
                        let comp = match rng.below(4) {
                            0 => component_type::VSTACK,
                            1 => component_type::HSTACK,
                            _ => component_type::TEXT,
                        };
                        g.create_node(node_counter, comp).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::TREE,
                            pathland_opcode::tree::CREATE_NODE,
                            0,
                            node_counter,
                            comp as u32,
                            0,
                        ));
                    }
                    1 => {
                        let id = node_counter.max(1);
                        let value = rng.next_u32();
                        g.set_property(id, property_id::COLOR, value_type::U32, value).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::STYLE,
                            pathland_opcode::style::SET_PROPERTY,
                            0,
                            id,
                            (value_type::U32 as u32) << 16 | property_id::COLOR as u32,
                            value,
                        ));
                    }
                    2 => {
                        let id = node_counter.max(1);
                        let parent = node_counter.saturating_sub(1);
                        g.insert_child(parent, id, APPEND).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::TREE,
                            pathland_opcode::tree::INSERT_CHILD,
                            0,
                            parent,
                            id,
                            APPEND,
                        ));
                    }
                    3 => {
                        // Variable-length text via the arena.
                        let id = node_counter.max(1);
                        let len = (rng.below(12) as usize) + 1;
                        let text: String = (0..len)
                            .map(|i| char::from(b'a' + ((i as u32 + rng.next_u32()) % 26) as u8))
                            .collect();
                        let arena_ref = g.set_text(id, &text).unwrap();
                        arena_strings.push((arena_ref, text));
                        expected.push(Opcode::new(
                            pathland_opcode::category::STYLE,
                            pathland_opcode::style::SET_TEXT,
                            0,
                            id,
                            arena_ref,
                            0,
                        ));
                    }
                    4 => {
                        if node_counter > 0 {
                            g.delete_node(node_counter).unwrap();
                            expected.push(Opcode::new(
                                pathland_opcode::category::TREE,
                                pathland_opcode::tree::DELETE_NODE,
                                0,
                                node_counter,
                                0,
                                0,
                            ));
                        }
                    }
                    _ => {
                        // reset is allowed mid-stream; META crosses the ring too.
                        g.reset().unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::META,
                            pathland_opcode::meta::RESET,
                            0,
                            0,
                            0,
                            0,
                        ));
                    }
                }
            }
            g.end_frame();
        }
    }

    // Drain everything the guest produced and compare field-for-field.
    let mut h = Host::new(&mut mem, &layout);
    let frames = h.frames();
    assert_eq!(frames.len(), 1);
    let frame = &frames[0];

    let actual: Vec<Opcode> = frame.opcodes().collect();
    assert_eq!(actual.len(), expected.len(), "opcode count mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_eq!(a.category(), e.category(), "category mismatch at {i}");
        assert_eq!(a.command(), e.command(), "command mismatch at {i}");
        assert_eq!(a.flags(), e.flags(), "flags mismatch at {i}");
        assert_eq!(a.a(), e.a(), "a mismatch at {i}");
        assert_eq!(a.b(), e.b(), "b mismatch at {i}");
        assert_eq!(a.c(), e.c(), "c mismatch at {i}");
    }

    // Arena strings must all be readable and match.
    for (offset, text) in &arena_strings {
        assert_eq!(frame.arena_str(*offset).unwrap(), text.as_str());
    }
}

